/// <summary>
/// This class used for extension of VendProductReceiptLineEntity.
/// </summary>
[ExtensionOf(tableStr(VendProductReceiptLineEntity))]
internal final class METVendProductReceiptLineEntity_Extension
{
}

Method.Source:
/// <summary>
/// This method used for populating a value to the METGSTPercent computed coloumn.
/// </summary>
/// <returns>The value of the <c>GST value</c> </returns>
public static str getGST()
{
    // Reference fields from the entity's data source (PurchLine)
    str taxGroup = SysComputedColumn::returnField(
    tableStr(VendProductReceiptLineEntity),
    identifierStr(PurchLine),
    fieldStr(PurchLine, TaxGroup));

    str taxItemGroup = SysComputedColumn::returnField(
    tableStr(VendProductReceiptLineEntity),
    identifierStr(PurchLine),
    fieldStr(PurchLine, TaxItemGroup));

    anytype legalEntity = SysComputedColumn::returnField(
        tableStr(VendProductReceiptLineEntity), identifierStr(VendPackingSlipTrans),
        fieldStr(VendPackingSlipTrans, DataAreaId));

    // The code with GST per cent value (i.e <>0) should be fetched.
    //  Multiple GST codes with % is not valid for POs.The expectation is that PO will have only one GST code with a GST % value.
    str gstPrcnt = strFmt(
    "SELECT ISNULL(MAX(TD.TAXVALUE), 0.00) "  +
    "FROM TAXGROUPDATA AS TGD " +
    "JOIN TAXONITEM AS TOI ON TOI.TAXCODE = TGD.TAXCODE AND TOI.DATAAREAID = TGD.DATAAREAID " +
    "JOIN TAXDATA AS TD ON TD.TAXCODE = TGD.TAXCODE AND TD.DATAAREAID = TGD.DATAAREAID " +
    "WHERE TGD.TAXGROUP = %1 "   +
    "AND TOI.TAXITEMGROUP = %2 " +
    "AND TGD.DATAAREAID = %3 "   +
    "AND TD.TAXVALUE <> 0 " +
    "AND (TD.TAXFROMDATE <= '1900-01-01 00:00:00.000' " + " OR (TD.TAXFROMDATE <= GETDATE() AND TD.TAXTODATE >= GETDATE()))",
    taxGroup, taxItemGroup, legalEntity);

    return gstPrcnt ;
}
